import pickle,numpy as np
with open('converted_data.pkl','rb') as f:d=pickle.load(f)
issues=[]
assert np.allclose(d['input'][0][0][0],np.arange(-.49,1.5,.02))
for s,(ns,ins,outs,ri,info) in enumerate(zip(d['neural'],d['input'],d['output'],d['brain_region_idx'],d['metadata']['session_info'])):
 n=ns[0].shape[0]
 if len(ns)!=len(ins) or len(ns)!=len(outs) or len(ns)<2: issues.append((s,'trial list lengths'))
 if len(ri)!=n or info['retained_units']!=n or info['retained_trials']!=len(ns): issues.append((s,'metadata/unit mismatch'))
 src=np.asarray(info['source_trial_indices'])
 if len(src)!=len(ns) or np.any(np.diff(src)<=0): issues.append((s,'source indices'))
 for j,(x,i,o) in enumerate(zip(ns,ins,outs)):
  if x.shape!=(n,100) or i.shape!=(2,100) or o.shape!=(4,100): issues.append((s,j,'shape'))
  if not np.isfinite(x).all() or not np.isfinite(i).all(): issues.append((s,j,'nonfinite'))
  if not np.allclose(i[0],np.arange(-.49,1.5,.02)): issues.append((s,j,'time grid'))
  if not np.all(i[1]==i[1,0]) or not np.all(o[:2]==o[:2,:1]): issues.append((s,j,'per-trial repeat'))
  if x.min()<0 or not np.allclose(x,np.round(x)): issues.append((s,j,'spike counts'))
print('audit issues',issues[:20],'count',len(issues))
print('sessions with root units',sum('root' in [d['brain_regions'][q] for q in ri] for ri in d['brain_region_idx']))
print('all metadata cameras',sorted(set(x['motion_camera'] for x in d['metadata']['session_info'])))
print('max spike count',max(float(x.max()) for ss in d['neural'] for x in ss))
print('source index ranges',[(x['source_trial_indices'][0],x['source_trial_indices'][-1]) for x in d['metadata']['session_info'][:5]])
